-- Project Ambrose by Imjustchico
-- Adds the classes a zone's triggers.xml, volumes.xml and trigger_groups.xml are written in, which the r806919 type dump does not describe and no install text names: their roots TriggerList, TriggerVolumeList and TriggerGroupList, the Trigger, TriggerObjectInfo, TriggerVolume and TriggerGroup they hold, the StateTrigger some of them hold, and the four trigger results the files use that the dump leaves out. Each is an authored row whose hashes the loader checks against the client's formula, and whose evidence says where the name comes from.
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `source` = VALUES(`source`), `evidence` = VALUES(`evidence`);

ON DUPLICATE KEY UPDATE `base_name` = VALUES(`base_name`);

ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `type` = VALUES(`type`), `hash` = VALUES(`hash`), `container` = VALUES(`container`), `offset` = VALUES(`offset`), `flags` = VALUES(`flags`), `dynamic` = VALUES(`dynamic`), `singleton` = VALUES(`singleton`), `pointer` = VALUES(`pointer`);

ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `value` = VALUES(`value`);
