INSERT INTO `server_class` (`hash`, `name`, `source`, `evidence`) VALUES
    (114994243, 'class TriggerList', 'authored', 'The root of every zone''s triggers.xml (3377 in the r806919 install, WizardCity-WC_Hub first), whose one property is its list of triggers. No install text holds the class name; a search of name forms found TriggerList, and m_allTriggers typed with a SharedPointer to Trigger hashes to the property the files hold. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_allTriggers is named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it.'),
    (109848155, 'class Trigger', 'authored', 'Every entry of TriggerList.m_allTriggers. WizardCity-WC_Hub''s trig_backup_saveme.notxml spells class.Trigger, and the roadmap''s hash for it matches. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_triggerName, m_triggerMax, m_cooldown, m_activateEvents, m_fireEvents, m_deactivateEvents, m_requirements, m_results, m_triggerObjectInfo are named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it. m_cooldownResults is held by no dump, text or program string; a word search named it and the values the files hold fit the name. #780900737, #847435658, #1549045087, #2293879431 keep their hashes, no candidate name fitting.'),
    (558354832, 'class TriggerObjectInfo', 'authored', 'The object a Trigger places, and the base of TriggerVolume. trig_backup_saveme.notxml spells class.TriggerObjectInfo; m_loadingType takes the options the type dump gives CoreObjectInfo::LoadingType. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_nObjectID, m_location, m_orientation, m_fScale, m_zoneTag, m_startState, m_overrideName, m_globalDynamic, m_bUndetectable, m_spawnRequirements, m_loadingType, m_triggerObjName, m_locationX, m_locationY, m_locationZ, m_templateID are named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it.'),
    (201234632, 'class StateTrigger', 'authored', 'An entry of TriggerList.m_allTriggers in 10 zones, 17 in all, a Trigger that also holds a state it requires, every property of Trigger among its own. The name-form search of Trigger class names found StateTrigger, the one form of those tried that hashes to the class the files give; the type dump names m_questEvent and m_requiredState at these types, and m_requiredQuest, always empty in the install, was found by the three-word search beside it. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_triggerName, m_triggerMax, m_cooldown, m_activateEvents, m_fireEvents, m_deactivateEvents, m_requirements, m_results, m_triggerObjectInfo, m_questEvent, m_requiredState are named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it. m_cooldownResults, m_requiredQuest are held by no dump, text or program string; a word search named them and the values the files hold fit the name. #780900737, #847435658, #1549045087, #2293879431, #333662217, #758563334, #1521843245, #3350245995, #3431571632 keep their hashes, no candidate name fitting.'),
    (460257136, 'class TriggerVolumeList', 'authored', 'The root of every zone''s volumes.xml (3377 in the install). No install text holds the class name; the name-form search found TriggerVolumeList, and m_allVolumes typed with a pointer to TriggerVolume hashes to the property the files hold. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_allVolumes is held by no dump, text or program string; a word search named it and the values the files hold fit the name.'),
    (461067766, 'class TriggerVolume', 'authored', 'Every entry of TriggerVolumeList.m_allVolumes, a TriggerObjectInfo with a shape; its properties follow the base''s in the files. The roadmap''s hash for it matches. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_nObjectID, m_location, m_orientation, m_fScale, m_zoneTag, m_startState, m_overrideName, m_globalDynamic, m_bUndetectable, m_spawnRequirements, m_loadingType, m_triggerObjName, m_locationX, m_locationY, m_locationZ, m_templateID, m_radius, m_length, m_width are named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it. m_shape, m_depth, m_questEvents, m_playerOnly, m_enterEvents, m_exitEvents are held by no dump, text or program string; a word search named them and the values the files hold fit the name.'),
    (1021044609, 'class TriggerGroupList', 'authored', 'The root of every zone''s trigger_groups.xml (3377 in the install). No install text holds the class name; the name-form search found TriggerGroupList, and m_allTriggerGroups typed with a SharedPointer to TriggerGroup hashes to the property the files hold. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_allTriggerGroups is held by no dump, text or program string; a word search named it and the values the files hold fit the name.'),
    (215698069, 'class TriggerGroup', 'authored', 'Every entry of TriggerGroupList.m_allTriggerGroups, a named list of trigger names. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_triggerNames, m_groupName are held by no dump, text or program string; a word search named them and the values the files hold fit the name.'),
    (2001472307, 'class ResClientNotifyText', 'authored', 'A result in the ResultList of zone triggers. The r806919 client program registers a factory under this name, which hashes to the class the files give, but the type dump does not describe it. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_text, m_type, m_radius are named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it. m_volumeX, m_volumeY, m_volumeZ are held by no dump, text or program string; a word search named them and the values the files hold fit the name. #783721823, #2122593183, #1475192380 keep their hashes, no candidate name fitting.'),
    (3938346, 'class ResAddDynaMod', 'authored', 'A result in the ResultList of zone triggers. The r806919 client program registers a factory under this name, which hashes to the class the files give, but the type dump does not describe it. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_zoneName is named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it. m_dynaModClientTag, m_dynaModRemove, m_dynaModState are held by no dump, text or program string; a word search named them and the values the files hold fit the name. #1110452292, #35044672, #1494302749 keep their hashes, no candidate name fitting.'),
    (338444955, 'class ResActorDialog', 'authored', 'A result in the ResultList of zone triggers. The r806919 client program registers a factory under this name, which hashes to the class the files give, but the type dump does not describe it. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_dialog, m_activePersona, m_quest, m_registryEntry are named as the type dump names a property of the same type, or as trig_backup_saveme.notxml spells it. m_oneShot, m_dialogPrefix, m_randomDialog are held by no dump, text or program string; a word search named them and the values the files hold fit the name. #2057644325, #482239118, #3080774699, #3156276983, #2216315577 keep their hashes, no candidate name fitting.'),
    (807468757, 'class ResDownloadPackage', 'authored', 'A result in the ResultList of zone triggers. The r806919 client program registers a factory under this name, which hashes to the class the files give, but the type dump does not describe it. The whole release sweep of the install (3589 wads) decodes every file holding it with no failure. m_packageList is held by no dump, text or program string; a word search named it and the values the files hold fit the name.')
